-- resume-public seed: public résumé tables copied verbatim from resume-backlog.
-- Generated once at split time. resume-backlog is never written to.

CREATE TABLE IF NOT EXISTS companies (key TEXT PRIMARY KEY, display TEXT, location TEXT, sort_order INTEGER);
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY, company_key TEXT, title TEXT, start TEXT, end TEXT, note TEXT, sort_order INTEGER);
CREATE TABLE IF NOT EXISTS accomplishments (id INTEGER PRIMARY KEY AUTOINCREMENT, role_id INTEGER, bullet TEXT, tags TEXT, metric TEXT, date_added TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS targets (name TEXT PRIMARY KEY, headline TEXT, summary TEXT, include_tags TEXT, boost_tags TEXT, exclude_tags TEXT, max_bullets_per_role INTEGER, num_highlights INTEGER);
CREATE TABLE IF NOT EXISTS profile (section TEXT, key TEXT, value TEXT);

